# -*- coding: utf-8 -*-
# sem1_ds_data.py - Complete Data Structures using C++ dataset

def get_ds_data():
    return {'id': 'data-structures', 'code': 'AIML-102', 'name': 'Data Structures using C++', 'subtitle': 'Pointers, OOP, Operator Overloading & Generic Templates', 'stats': {'topics': 8, 'assignments': 49, 'demos': 1}, 'overview': 'Rigorous treatment of memory architecture, pointers, dynamic allocation, C++ OOP design patterns, operator overloading, stream manipulation, templates, and fundamental algorithmic data structures.', 'topics': [{'id': 'ds-t1', 'title': 'C Pointers, Memory Model & DMA', 'tag': 'C Core', 'content': '\n              <p>Pointers store physical memory addresses. In C, dynamic memory allocation occurs in the <strong>Heap</strong> segment via four standard runtime functions:</p>\n              <ul>\n                <li><code>malloc(size_t size)</code>: Allocates uninitialized memory chunk of specified byte size.</li>\n                <li><code>calloc(size_t num, size_t size)</code>: Allocates contiguous block zero-initializing all bytes.</li>\n                <li><code>realloc(void *ptr, size_t new_size)</code>: Resizes existing allocated block, migrating contents if memory expansion requires relocation.</li>\n                <li><code>free(void *ptr)</code>: Deallocates heap memory back to the OS runtime pool, preventing memory leaks.</li>\n              </ul>\n              <div class="callout callout-warning">\n                <div class="callout-title">Dangling Pointers & Memory Leaks</div>\n                <p>Always set deallocated pointers to <code>NULL</code> immediately after <code>free(ptr)</code> to prevent accessing freed heap memory.</p>\n              </div>\n            '}, {'id': 'ds-t2', 'title': 'Storage Classes & Preprocessor Directives', 'tag': 'Architecture', 'content': '\n              <p>Storage classes define variable scope, lifetime, and storage location:</p>\n              <div class="data-table-wrapper">\n                <table class="data-table">\n                  <thead><tr><th>Storage Class</th><th>Keyword</th><th>Location</th><th>Default Value</th><th>Scope</th><th>Lifetime</th></tr></thead>\n                  <tbody>\n                    <tr><td>Automatic</td><td><code>auto</code></td><td>Stack</td><td>Garbage</td><td>Block</td><td>End of block</td></tr>\n                    <tr><td>Register</td><td><code>register</code></td><td>CPU Register</td><td>Garbage</td><td>Block</td><td>End of block</td></tr>\n                    <tr><td>Static</td><td><code>static</code></td><td>Data Segment</td><td>Zero</td><td>File / Block</td><td>Entire Program</td></tr>\n                    <tr><td>External</td><td><code>extern</code></td><td>Data Segment</td><td>Zero</td><td>Global across files</td><td>Entire Program</td></tr>\n                  </tbody>\n                </table>\n              </div>\n            '}, {'id': 'ds-t3', 'title': 'C++ OOP Principles & Encapsulation', 'tag': 'OOP Core', 'content': '\n              <p>C++ introduces class-based Object-Oriented Programming (OOP) enforcing four pillars:</p>\n              <ol>\n                <li><strong>Encapsulation:</strong> Bundling data members and member functions into classes with access specifiers (<code>private</code>, <code>protected</code>, <code>public</code>).</li>\n                <li><strong>Abstraction:</strong> Exposing essential interface contracts while concealing internal algorithmic and memory management mechanisms.</li>\n                <li><strong>Inheritance:</strong> Reusing code and establishing hierarchical polymorphism.</li>\n                <li><strong>Polymorphism:</strong> Compile-time (function overloading, operator overloading, templates) and Run-time (virtual functions, dynamic dispatch via vtable).</li>\n              </ol>\n            '}, {'id': 'ds-t4', 'title': 'Operator Overloading Mechanics', 'tag': 'Polymorphism', 'content': '\n              <p>Operator overloading allows user-defined types to exhibit natural mathematical syntax. Syntax:</p>\n              <pre><code>ReturnType operator Symbol(ParameterList) { /* body */ }</code></pre>\n              <div class="callout callout-info">\n                <div class="callout-title">Operators That CANNOT Be Overloaded</div>\n                <p>For safety and compiler integrity, C++ forbids overloading: <code>.</code> (member access), <code>.*</code> (pointer-to-member), <code>::</code> (scope resolution), <code>?:</code> (ternary conditional), and <code>sizeof</code>.</p>\n              </div>\n            '}, {'id': 'ds-t5', 'title': 'Friend Functions & Friend Classes', 'tag': 'OOP Mechanics', 'content': '\n              <p>A <code>friend</code> function is a non-member function granted explicit access to <code>private</code> and <code>protected</code> members of a class. Commonly utilized for:</p>\n              <ul>\n                <li>Commutative operator overloading (e.g. <code>5 * matrix</code> where the left operand is a primitive).</li>\n                <li>Stream extraction and insertion operators: <code>friend ostream& operator<<(ostream&, const T&);</code>.</li>\n                <li>Bridging tight algorithmic dependencies between two separate classes without exposing full public mutators.</li>\n              </ul>\n            '}, {'id': 'ds-t6', 'title': 'Templates & Generic Programming', 'tag': 'Generics', 'content': '\n              <p>Templates implement compile-time parametric polymorphism, generating specialized machine code on demand for specific data types:</p>\n              <pre><code>template &lt;typename T&gt;\nT findMax(T a, T b) {\n    return (a > b) ? a : b;\n}</code></pre>\n              <p>Class templates instantiate container classes (such as vectors, stacks, queues) that operate uniformly across primitives and complex objects.</p>\n            '}, {'id': 'ds-t7', 'title': 'Inheritance Models & Virtual Base Classes', 'tag': 'Inheritance', 'content': '\n              <p>Inheritance enables code reuse across single, multilevel, multiple, and hierarchical topologies. The <strong>Diamond Problem</strong> occurs in multiple inheritance when a class inherits from two classes that share a common ancestor.</p>\n              <div class="callout callout-warning">\n                <div class="callout-title">Resolving the Diamond Problem with Virtual Base Classes</div>\n                <p>Declare the common ancestor as <code>virtual</code>: <code>class B : virtual public A { ... };</code>. This instructs the compiler to retain only a single instance of class A in the leaf object.</p>\n              </div>\n            '}, {'id': 'ds-t8', 'title': 'Linear & Non-Linear Data Structures Overview', 'tag': 'Data Structures', 'content': '\n              <p>Data structure foundations utilized throughout machine learning engineering:</p>\n              <ul>\n                <li><strong>Arrays & Vectors:</strong> Contiguous memory, \\(O(1)\\) indexing, \\(O(N)\\) insertion/deletion.</li>\n                <li><strong>Singly & Doubly Linked Lists:</strong> Dynamic pointer nodes, \\(O(1)\\) head/tail modification, \\(O(N)\\) traversal.</li>\n                <li><strong>Stacks (LIFO) & Queues (FIFO):</strong> Essential for recursion backtracking, parsing, and BFS traversal.</li>\n                <li><strong>Binary Search Trees & Heaps:</strong> Priority queues, \\(O(\\log N)\\) search and insertion, Min/Max extraction.</li>\n              </ul>\n            '}], 'assignments': [{'id': 'c-pr1', 'title': 'C1: Maximum of Three Numbers', 'difficulty': 'Foundational', 'category': 'C Language Basics', 'question': 'Write a C program to determine the maximum of 3 numbers using conditional constructs.', 'solution': '<div class="solution-content">\n<p><strong>Logic & Approach:</strong> Read three integers from standard input. Use nested <code>if-else</code> or ternary expressions to evaluate the maximum with \\(O(1)\\) operations.</p>\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_max3">Copy</button></div>\n<pre><code id="c_max3">#include &lt;stdio.h&gt;\n\nint main() {\n    int a, b, c, max;\n    printf("Enter three integers: ");\n    if (scanf("%d %d %d", &a, &b, &c) != 3) {\n        printf("Invalid input. Please enter three valid integers.\\n");\n        return 1;\n    }\n    \n    if (a >= b && a >= c) {\n        max = a;\n    } else if (b >= a && b >= c) {\n        max = b;\n    } else {\n        max = c;\n    }\n    \n    printf("Maximum number among (%d, %d, %d) is: %d\\n", a, b, c, max);\n    return 0;\n}</code></pre>\n<p><strong>Sample Input / Output:</strong></p>\n<pre><code>Enter three integers: 45 92 18\nMaximum number among (45, 92, 18) is: 92</code></pre>\n</div>'}, {'id': 'c-pr2', 'title': 'C2: Convert Days to Years, Months, and Remaining Days', 'difficulty': 'Foundational', 'category': 'C Language Basics', 'question': 'Write a program to accept number of days and print year, month and remaining days.', 'solution': '<div class="solution-content">\n<p><strong>Logic:</strong> Standard conversion using integer division and modulo: 1 year = 365 days, 1 month = 30 days.</p>\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_days">Copy</button></div>\n<pre><code id="c_days">#include &lt;stdio.h&gt;\n\nint main() {\n    int total_days;\n    printf("Enter total number of days: ");\n    if (scanf("%d", &total_days) != 1 || total_days < 0) {\n        printf("Invalid input. Total days must be non-negative.\\n");\n        return 1;\n    }\n    \n    int years = total_days / 365;\n    int rem_after_years = total_days % 365;\n    int months = rem_after_years / 30;\n    int days = rem_after_years % 30;\n    \n    printf("%d Days = %d Year(s), %d Month(s), and %d Day(s)\\n", \n           total_days, years, months, days);\n    return 0;\n}</code></pre>\n<p><strong>Sample Input / Output:</strong></p>\n<pre><code>Enter total number of days: 800\n800 Days = 2 Year(s), 2 Month(s), and 10 Day(s)</code></pre>\n</div>'}, {'id': 'c-pr3', 'title': 'C3: Swap Values of Two Variables', 'difficulty': 'Foundational', 'category': 'C Language Basics', 'question': 'Write a program to swap the values of two variables (demonstrating both temporary variable and bitwise XOR arithmetic approaches).', 'solution': '<div class="solution-content">\n<p><strong>Approaches:</strong> (1) Auxiliary variable, (2) Arithmetic addition/subtraction, (3) Bitwise XOR without overflow risk.</p>\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_swap">Copy</button></div>\n<pre><code id="c_swap">#include &lt;stdio.h&gt;\n\nint main() {\n    int x, y, temp;\n    printf("Enter two numbers (x and y): ");\n    scanf("%d %d", &x, &y);\n    printf("Original: x = %d, y = %d\\n", x, y);\n\n    // Method 1: Using temporary variable\n    temp = x;\n    x = y;\n    y = temp;\n    printf("After swap (using temp): x = %d, y = %d\\n", x, y);\n\n    // Method 2: In-place using bitwise XOR\n    x = x ^ y;\n    y = x ^ y;\n    x = x ^ y;\n    printf("Swapped back (using XOR): x = %d, y = %d\\n", x, y);\n\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr4', 'title': 'C4: Student Grading and Class Determination', 'difficulty': 'Foundational', 'category': 'Conditional Logic', 'question': 'Write a program that reads the percentage obtained by the students and determines and prints the class obtained by the student as per the following rules: 0-39: Fail, 40-59: Second class, 60-79: First class, 80-100: Distinction.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_grade">Copy</button></div>\n<pre><code id="c_grade">#include &lt;stdio.h&gt;\n\nint main() {\n    float percentage;\n    printf("Enter student percentage (0 - 100): ");\n    if (scanf("%f", &percentage) != 1 || percentage < 0.0 || percentage > 100.0) {\n        printf("Validation Error: Percentage must lie between 0.0 and 100.0\\n");\n        return 1;\n    }\n\n    printf("Percentage: %.2f%% -> Result: ", percentage);\n    if (percentage >= 80.0) {\n        printf("Distinction\\n");\n    } else if (percentage >= 60.0) {\n        printf("First Class\\n");\n    } else if (percentage >= 40.0) {\n        printf("Second Class\\n");\n    } else {\n        printf("Fail\\n");\n    }\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr5', 'title': 'C5: Area of Shapes using Symbolic Constants and Switch', 'difficulty': 'Foundational', 'category': 'C Language Basics', 'question': "Write a program to calculate the area of circle/rectangle/triangle. 'C' indicates circle, 'R' indicates rectangle, 'T' indicates triangle. Use symbolic constant to define the value of PI.", 'solution': '<div class="solution-content">\n<p>Uses <code>#define PI 3.141592653589793</code> and <code>switch(toupper(choice))</code>.</p>\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_area">Copy</button></div>\n<pre><code id="c_area">#include &lt;stdio.h&gt;\n#include &lt;ctype.h&gt;\n\n#define PI 3.141592653589793\n\nint main() {\n    char choice;\n    printf("Select Shape [C: Circle, R: Rectangle, T: Triangle]: ");\n    scanf(" %c", &choice);\n    choice = toupper(choice);\n\n    switch(choice) {\n        case \'C\': {\n            double r;\n            printf("Enter radius of circle: ");\n            scanf("%lf", &r);\n            if (r < 0) { printf("Error: Radius cannot be negative.\\n"); return 1; }\n            printf("Area of Circle = %.4lf\\n", PI * r * r);\n            break;\n        }\n        case \'R\': {\n            double l, b;\n            printf("Enter length and breadth: ");\n            scanf("%lf %lf", &l, &b);\n            if (l < 0 || b < 0) { printf("Error: Dimensions must be non-negative.\\n"); return 1; }\n            printf("Area of Rectangle = %.4lf\\n", l * b);\n            break;\n        }\n        case \'T\': {\n            double b, h;\n            printf("Enter base and height: ");\n            scanf("%lf %lf", &b, &h);\n            if (b < 0 || h < 0) { printf("Error: Dimensions must be non-negative.\\n"); return 1; }\n            printf("Area of Triangle = %.4lf\\n", 0.5 * b * h);\n            break;\n        }\n        default:\n            printf("Invalid selection! Use C, R, or T.\\n");\n            return 1;\n    }\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr6', 'title': 'C6: Total Salary Calculation (Basic, HRA, DA)', 'difficulty': 'Foundational', 'category': 'C Language Basics', 'question': 'Write a program that accepts basic, HRA, and DA from the user and calculates total salary.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_salary">Copy</button></div>\n<pre><code id="c_salary">#include &lt;stdio.h&gt;\n\nint main() {\n    double basic, hra, da, total_salary;\n    printf("Enter Basic Salary: ");\n    if (scanf("%lf", &basic) != 1 || basic < 0) {\n        printf("Error: Basic salary must be non-negative.\\n");\n        return 1;\n    }\n    printf("Enter HRA and DA: ");\n    scanf("%lf %lf", &hra, &da);\n\n    total_salary = basic + hra + da;\n    printf("--- Salary Breakdown ---\\n");\n    printf("Basic: %.2lf | HRA: %.2lf | DA: %.2lf\\n", basic, hra, da);\n    printf("Total Gross Salary = %.2lf\\n", total_salary);\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr7', 'title': 'C7: Print 1 to 10 Using While, Do-While, and For Loops', 'difficulty': 'Foundational', 'category': 'Loops & Iterations', 'question': 'Using While, do..while and for loop print 1 2 3 4 5 ... 10.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_loops1">Copy</button></div>\n<pre><code id="c_loops1">#include &lt;stdio.h&gt;\n\nint main() {\n    int i;\n\n    // 1. For loop\n    printf("Using FOR loop:     ");\n    for (i = 1; i <= 10; i++) {\n        printf("%d ", i);\n    }\n    printf("\\n");\n\n    // 2. While loop\n    printf("Using WHILE loop:   ");\n    i = 1;\n    while (i <= 10) {\n        printf("%d ", i);\n        i++;\n    }\n    printf("\\n");\n\n    // 3. Do-While loop\n    printf("Using DO-WHILE loop:");\n    i = 1;\n    do {\n        printf("%d ", i);\n        i++;\n    } while (i <= 10);\n    printf("\\n");\n\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr8', 'title': 'C8: Even Series 2, 4, 6, 8, ... n', 'difficulty': 'Foundational', 'category': 'Loops & Iterations', 'question': 'Print series 2, 4, 6, 8, ... n using While, do..while and for loop.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_even_series">Copy</button></div>\n<pre><code id="c_even_series">#include &lt;stdio.h&gt;\n\nint main() {\n    int n, i;\n    printf("Enter upper bound n: ");\n    if (scanf("%d", &n) != 1 || n < 2) {\n        printf("Please enter an integer >= 2.\\n");\n        return 1;\n    }\n\n    printf("For loop:      ");\n    for (i = 2; i <= n; i += 2) printf("%d ", i);\n    printf("\\n");\n\n    printf("While loop:    ");\n    i = 2;\n    while (i <= n) { printf("%d ", i); i += 2; }\n    printf("\\n");\n\n    printf("Do-While loop: ");\n    i = 2;\n    do { printf("%d ", i); i += 2; } while (i <= n);\n    printf("\\n");\n\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr9', 'title': 'C9: Power Series 2, 4, 16, ... n*n', 'difficulty': 'Foundational', 'category': 'Loops & Iterations', 'question': 'Print series 2, 4, 16, ... n*n (Using While, do..while and for loop).', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_sq_series">Copy</button></div>\n<pre><code id="c_sq_series">#include &lt;stdio.h&gt;\n\nint main() {\n    long long limit;\n    printf("Enter limit value: ");\n    if (scanf("%lld", &limit) != 1 || limit < 2) {\n        printf("Limit must be >= 2.\\n");\n        return 1;\n    }\n\n    printf("For loop:      ");\n    for (long long val = 2; val <= limit; val = val * val) {\n        printf("%lld ", val);\n    }\n    printf("\\n");\n\n    printf("While loop:    ");\n    long long w = 2;\n    while (w <= limit) {\n        printf("%lld ", w);\n        w = w * w;\n    }\n    printf("\\n");\n\n    printf("Do-While loop: ");\n    long long d = 2;\n    do {\n        printf("%lld ", d);\n        d = d * d;\n    } while (d <= limit);\n    printf("\\n");\n\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr10', 'title': 'C10: Average of a Set of n Given Numbers', 'difficulty': 'Foundational', 'category': 'Loops & Iterations', 'question': 'Write a program to calculate the average of a set of n given numbers.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_avg">Copy</button></div>\n<pre><code id="c_avg">#include &lt;stdio.h&gt;\n\nint main() {\n    int n;\n    double sum = 0.0, num;\n    printf("Enter count of numbers (n): ");\n    if (scanf("%d", &n) != 1 || n <= 0) {\n        printf("Error: n must be a positive integer.\\n");\n        return 1;\n    }\n\n    printf("Enter %d numbers:\\n", n);\n    for (int i = 0; i < n; i++) {\n        scanf("%lf", &num);\n        sum += num;\n    }\n\n    printf("Sum = %.4lf, Average = %.4lf\\n", sum, sum / n);\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr11', 'title': 'C11: Fibonacci Series Generation', 'difficulty': 'Foundational', 'category': 'Loops & Iterations', 'question': 'Write a program to generate Fibonacci series up to n terms.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_fibo">Copy</button></div>\n<pre><code id="c_fibo">#include &lt;stdio.h&gt;\n\nint main() {\n    int n;\n    printf("Enter number of terms: ");\n    if (scanf("%d", &n) != 1 || n <= 0) {\n        printf("Enter positive number of terms.\\n");\n        return 1;\n    }\n\n    long long first = 0, second = 1, next;\n    printf("Fibonacci Series (%d terms):\\n", n);\n    for (int i = 1; i <= n; i++) {\n        if (i == 1) {\n            printf("%lld ", first);\n        } else if (i == 2) {\n            printf("%lld ", second);\n        } else {\n            next = first + second;\n            first = second;\n            second = next;\n            printf("%lld ", next);\n        }\n    }\n    printf("\\n");\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr12', 'title': 'C12: Multiplication Table', 'difficulty': 'Foundational', 'category': 'Loops & Iterations', 'question': 'Write a program to print the multiplication table of a given number.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_table">Copy</button></div>\n<pre><code id="c_table">#include &lt;stdio.h&gt;\n\nint main() {\n    int num, range;\n    printf("Enter integer for multiplication table: ");\n    scanf("%d", &num);\n    printf("Enter range (e.g. 10): ");\n    scanf("%d", &range);\n\n    printf("Multiplication Table for %d:\\n", num);\n    for (int i = 1; i <= range; i++) {\n        printf("%d x %2d = %d\\n", num, i, num * i);\n    }\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr13', 'title': 'C13: Factorial of an Entered Number', 'difficulty': 'Foundational', 'category': 'Loops & Iterations', 'question': 'Write a program to find the factorial of the entered number with input validation.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_fact">Copy</button></div>\n<pre><code id="c_fact">#include &lt;stdio.h&gt;\n\nunsigned long long factorial(int n) {\n    if (n == 0 || n == 1) return 1ULL;\n    return n * factorial(n - 1);\n}\n\nint main() {\n    int n;\n    printf("Enter non-negative integer (0-20): ");\n    if (scanf("%d", &n) != 1 || n < 0 || n > 20) {\n        printf("Error: Input must be between 0 and 20 (to avoid 64-bit integer overflow).\\n");\n        return 1;\n    }\n\n    printf("%d! = %llu\\n", n, factorial(n));\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr14', 'title': 'C14: Integers Divisible by 7 Between 100 and 200', 'difficulty': 'Foundational', 'category': 'Loops & Iterations', 'question': 'Write a program to print all the numbers and sum of all the integers that are greater than 100 and less than 200 and are divisible by 7.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_div7">Copy</button></div>\n<pre><code id="c_div7">#include &lt;stdio.h&gt;\n\nint main() {\n    int sum = 0, count = 0;\n    printf("Integers between 100 and 200 divisible by 7:\\n");\n    for (int i = 101; i < 200; i++) {\n        if (i % 7 == 0) {\n            printf("%d ", i);\n            sum += i;\n            count++;\n        }\n    }\n    printf("\\nTotal Count: %d | Sum: %d\\n", count, sum);\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr15', 'title': 'C15: Basic Calculator Using Switch-Case', 'difficulty': 'Foundational', 'category': 'Conditional Logic', 'question': 'Write a program to accept two numbers and perform basic operations of calculator (+, -, *, /) using switch-case.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_calc">Copy</button></div>\n<pre><code id="c_calc">#include &lt;stdio.h&gt;\n\nint main() {\n    double n1, n2, result;\n    char op;\n    printf("Enter expression (e.g. 15.5 + 4.2): ");\n    if (scanf("%lf %c %lf", &n1, &op, &n2) != 3) {\n        printf("Invalid format! Use: number operator number\\n");\n        return 1;\n    }\n\n    switch(op) {\n        case \'+\': result = n1 + n2; break;\n        case \'-\': result = n1 - n2; break;\n        case \'*\': result = n1 * n2; break;\n        case \'/\':\n            if (n2 == 0.0) {\n                printf("Error: Division by zero is undefined!\\n");\n                return 1;\n            }\n            result = n1 / n2;\n            break;\n        default:\n            printf("Unsupported operator \'%c\'!\\n", op);\n            return 1;\n    }\n    printf("%.4lf %c %.4lf = %.4lf\\n", n1, op, n2, result);\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr16', 'title': 'C16: Star Patterns (Square, Triangle, Inverted, Hollow Square, Right-Aligned)', 'difficulty': 'Intermediate', 'category': 'Pattern Generation', 'question': 'Generate the 5 assignment patterns: (1) 5x5 Solid Square, (2) Left-aligned Triangle, (3) Inverted Left-aligned Triangle, (4) Hollow 5x5 Square, (5) Inverted Right-aligned Triangle.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_patterns">Copy</button></div>\n<pre><code id="c_patterns">#include &lt;stdio.h&gt;\n\nvoid pattern1(int n) { // Solid Square\n    for (int i = 0; i < n; i++) {\n        for (int j = 0; j < n; j++) printf("* ");\n        printf("\\n");\n    }\n}\n\nvoid pattern2(int n) { // Left-aligned Triangle\n    for (int i = 1; i <= n; i++) {\n        for (int j = 1; j <= i; j++) printf("* ");\n        printf("\\n");\n    }\n}\n\nvoid pattern3(int n) { // Inverted Left Triangle\n    for (int i = n; i >= 1; i--) {\n        for (int j = 1; j <= i; j++) printf("* ");\n        printf("\\n");\n    }\n}\n\nvoid pattern4(int n) { // Hollow Square\n    for (int i = 1; i <= n; i++) {\n        for (int j = 1; j <= n; j++) {\n            if (i == 1 || i == n || j == 1 || j == n) printf("* ");\n            else printf("  ");\n        }\n        printf("\\n");\n    }\n}\n\nvoid pattern5(int n) { // Inverted Right-aligned\n    for (int i = 0; i < n; i++) {\n        for (int s = 0; s < i; s++) printf("   ");\n        for (int j = 0; j < n - i; j++) printf("*  ");\n        printf("\\n");\n    }\n}\n\nint main() {\n    int n = 5;\n    printf("Pattern 1:\\n"); pattern1(n);\n    printf("\\nPattern 2:\\n"); pattern2(n);\n    printf("\\nPattern 3:\\n"); pattern3(n);\n    printf("\\nPattern 4:\\n"); pattern4(n);\n    printf("\\nPattern 5:\\n"); pattern5(n);\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr17', 'title': 'C17: Maximum Element in 1-D Array', 'difficulty': 'Foundational', 'category': 'Arrays & Pointers', 'question': 'Write a program to find maximum element from 1-Dimensional array.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_arr_max">Copy</button></div>\n<pre><code id="c_arr_max">#include &lt;stdio.h&gt;\n\nint main() {\n    int n;\n    printf("Enter number of elements: ");\n    if (scanf("%d", &n) != 1 || n <= 0) return 1;\n\n    int arr[n];\n    printf("Enter %d integers:\\n", n);\n    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);\n\n    int max_val = arr[0];\n    int max_idx = 0;\n    for (int i = 1; i < n; i++) {\n        if (arr[i] > max_val) {\n            max_val = arr[i];\n            max_idx = i;\n        }\n    }\n    printf("Maximum value is %d at index %d (position %d)\\n", max_val, max_idx, max_idx + 1);\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr18', 'title': 'C18: Sort Array in Ascending Order', 'difficulty': 'Foundational', 'category': 'Arrays & Pointers', 'question': 'Write a program to sort given array in ascending order.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_arr_sort">Copy</button></div>\n<pre><code id="c_arr_sort">#include &lt;stdio.h&gt;\n\nvoid bubbleSort(int arr[], int n) {\n    for (int i = 0; i < n - 1; i++) {\n        int swapped = 0;\n        for (int j = 0; j < n - i - 1; j++) {\n            if (arr[j] > arr[j + 1]) {\n                int temp = arr[j];\n                arr[j] = arr[j + 1];\n                arr[j + 1] = temp;\n                swapped = 1;\n            }\n        }\n        if (!swapped) break;\n    }\n}\n\nint main() {\n    int n;\n    printf("Enter size of array: ");\n    scanf("%d", &n);\n    int arr[n];\n    printf("Enter elements: ");\n    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);\n\n    bubbleSort(arr, n);\n    printf("Sorted Array in Ascending Order:\\n");\n    for (int i = 0; i < n; i++) printf("%d ", arr[i]);\n    printf("\\n");\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr19', 'title': 'C19: Merge Two Sorted 1-D Arrays', 'difficulty': 'Intermediate', 'category': 'Arrays & Pointers', 'question': 'Given two 1-D arrays A and B, which are sorted in ascending order. Write a program to merge them into a single sorted array C that contains every item from arrays A and B in ascending order (Linear O(N+M) two-pointer merge).', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_merge">Copy</button></div>\n<pre><code id="c_merge">#include &lt;stdio.h&gt;\n\nvoid mergeArrays(int A[], int n, int B[], int m, int C[]) {\n    int i = 0, j = 0, k = 0;\n    while (i < n && j < m) {\n        if (A[i] <= B[j]) {\n            C[k++] = A[i++];\n        } else {\n            C[k++] = B[j++];\n        }\n    }\n    while (i < n) C[k++] = A[i++];\n    while (j < m) C[k++] = B[j++];\n}\n\nint main() {\n    int n, m;\n    printf("Enter size of array A: ");\n    scanf("%d", &n);\n    int A[n];\n    printf("Enter %d sorted elements for A: ", n);\n    for (int i = 0; i < n; i++) scanf("%d", &A[i]);\n\n    printf("Enter size of array B: ");\n    scanf("%d", &m);\n    int B[m];\n    printf("Enter %d sorted elements for B: ", m);\n    for (int j = 0; j < m; j++) scanf("%d", &B[j]);\n\n    int C[n + m];\n    mergeArrays(A, n, B, m, C);\n\n    printf("Merged Sorted Array C (Size %d):\\n", n + m);\n    for (int k = 0; k < n + m; k++) printf("%d ", C[k]);\n    printf("\\n");\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr20', 'title': 'C20: Matrix Addition', 'difficulty': 'Foundational', 'category': 'Multidimensional Arrays', 'question': 'Write a program to add two matrices of order r x c.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_mat_add">Copy</button></div>\n<pre><code id="c_mat_add">#include &lt;stdio.h&gt;\n\nint main() {\n    int r, c;\n    printf("Enter matrix rows and columns: ");\n    scanf("%d %d", &r, &c);\n\n    int A[r][c], B[r][c], Sum[r][c];\n    printf("Enter elements of Matrix A:\\n");\n    for (int i = 0; i < r; i++)\n        for (int j = 0; j < c; j++)\n            scanf("%d", &A[i][j]);\n\n    printf("Enter elements of Matrix B:\\n");\n    for (int i = 0; i < r; i++)\n        for (int j = 0; j < c; j++)\n            scanf("%d", &B[i][j]);\n\n    for (int i = 0; i < r; i++)\n        for (int j = 0; j < c; j++)\n            Sum[i][j] = A[i][j] + B[i][j];\n\n    printf("Resultant Matrix A + B:\\n");\n    for (int i = 0; i < r; i++) {\n        for (int j = 0; j < c; j++)\n            printf("%4d ", Sum[i][j]);\n        printf("\\n");\n    }\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr21', 'title': 'C21: Matrix Multiplication', 'difficulty': 'Intermediate', 'category': 'Multidimensional Arrays', 'question': "Write a 'C' program that reads in two matrices and multiplies them. Display the resultant matrix with dimension verification (r1 x c1) * (r2 x c2).", 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_mat_mul">Copy</button></div>\n<pre><code id="c_mat_mul">#include &lt;stdio.h&gt;\n\nint main() {\n    int r1, c1, r2, c2;\n    printf("Enter rows & cols of Matrix A: ");\n    scanf("%d %d", &r1, &c1);\n    printf("Enter rows & cols of Matrix B: ");\n    scanf("%d %d", &r2, &c2);\n\n    if (c1 != r2) {\n        printf("Error: Matrix multiplication impossible! Col of A (%d) != Row of B (%d).\\n", c1, r2);\n        return 1;\n    }\n\n    int A[r1][c1], B[r2][c2], C[r1][c2];\n\n    printf("Enter Matrix A (%dx%d):\\n", r1, c1);\n    for (int i = 0; i < r1; i++)\n        for (int j = 0; j < c1; j++)\n            scanf("%d", &A[i][j]);\n\n    printf("Enter Matrix B (%dx%d):\\n", r2, c2);\n    for (int i = 0; i < r2; i++)\n        for (int j = 0; j < c2; j++)\n            scanf("%d", &B[i][j]);\n\n    // Multiply\n    for (int i = 0; i < r1; i++) {\n        for (int j = 0; j < c2; j++) {\n            C[i][j] = 0;\n            for (int k = 0; k < c1; k++) {\n                C[i][j] += A[i][k] * B[k][j];\n            }\n        }\n    }\n\n    printf("Resultant Matrix C (%dx%d):\\n", r1, c2);\n    for (int i = 0; i < r1; i++) {\n        for (int j = 0; j < c2; j++)\n            printf("%6d ", C[i][j]);\n        printf("\\n");\n    }\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr22', 'title': 'C22: Find Element at Given Position in 2-D Array', 'difficulty': 'Foundational', 'category': 'Multidimensional Arrays', 'question': 'Write a program to find element at given position from 2-Dimensional array.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_2d_pos">Copy</button></div>\n<pre><code id="c_2d_pos">#include &lt;stdio.h&gt;\n\nint main() {\n    int r, c;\n    printf("Enter rows and columns: ");\n    scanf("%d %d", &r, &c);\n    int mat[r][c];\n\n    printf("Enter elements of matrix (%dx%d):\\n", r, c);\n    for (int i = 0; i < r; i++)\n        for (int j = 0; j < c; j++)\n            scanf("%d", &mat[i][j]);\n\n    int target_r, target_c;\n    printf("Enter target position (1-based row and col): ");\n    scanf("%d %d", &target_r, &target_c);\n\n    if (target_r < 1 || target_r > r || target_c < 1 || target_c > c) {\n        printf("Index Out of Bounds! Range is [1..%d, 1..%d]\\n", r, c);\n        return 1;\n    }\n\n    printf("Element at row %d, col %d is: %d\\n", target_r, target_c, mat[target_r - 1][target_c - 1]);\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr23', 'title': 'C23: String Length Without strlen()', 'difficulty': 'Foundational', 'category': 'Strings & Pointers', 'question': 'Write a program to find string length without using built-in string functions.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_strlen">Copy</button></div>\n<pre><code id="c_strlen">#include &lt;stdio.h&gt;\n\nint custom_strlen(const char *str) {\n    int len = 0;\n    while (*(str + len) != \'\\0\') {\n        len++;\n    }\n    return len;\n}\n\nint main() {\n    char str[1000];\n    printf("Enter string: ");\n    if (fgets(str, sizeof(str), stdin) != NULL) {\n        // Strip trailing newline\n        int len = custom_strlen(str);\n        if (len > 0 && str[len - 1] == \'\\n\') {\n            str[len - 1] = \'\\0\';\n            len--;\n        }\n        printf("String: \\"%s\\" | Length: %d characters\\n", str, len);\n    }\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr24', 'title': 'C24: Count Word Occurrences in a String', 'difficulty': 'Intermediate', 'category': 'Strings & Pointers', 'question': 'Write a program that will input a string and count all occurrences of a particular word.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_word_count">Copy</button></div>\n<pre><code id="c_word_count">#include &lt;stdio.h&gt;\n#include &lt;string.h&gt;\n#include &lt;ctype.h&gt;\n\nint countWordOccurrences(const char *text, const char *word) {\n    int count = 0;\n    int wordLen = strlen(word);\n    const char *ptr = text;\n\n    while ((ptr = strstr(ptr, word)) != NULL) {\n        // Verify whole word boundaries\n        int left_boundary = (ptr == text || !isalnum(*(ptr - 1)));\n        int right_boundary = (!isalnum(*(ptr + wordLen)));\n\n        if (left_boundary && right_boundary) {\n            count++;\n        }\n        ptr += wordLen;\n    }\n    return count;\n}\n\nint main() {\n    char text[1000], word[100];\n    printf("Enter text: ");\n    fgets(text, sizeof(text), stdin);\n    printf("Enter word to search: ");\n    scanf("%s", word);\n\n    int count = countWordOccurrences(text, word);\n    printf("Word \\"%s\\" occurs %d time(s) as an independent token.\\n", word, count);\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr25', 'title': 'C25: Sort String in Alphabetical Order', 'difficulty': 'Intermediate', 'category': 'Strings & Pointers', 'question': 'Write a program that will read a string and rewrite it in alphabetical order.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_sort_str">Copy</button></div>\n<pre><code id="c_sort_str">#include &lt;stdio.h&gt;\n#include &lt;string.h&gt;\n\nvoid sortStringAlphabetical(char *str) {\n    int n = strlen(str);\n    for (int i = 0; i < n - 1; i++) {\n        for (int j = i + 1; j < n; j++) {\n            if (str[i] > str[j]) {\n                char temp = str[i];\n                str[i] = str[j];\n                str[j] = temp;\n            }\n        }\n    }\n}\n\nint main() {\n    char str[200];\n    printf("Enter a word or string: ");\n    scanf("%199s", str);\n\n    sortStringAlphabetical(str);\n    printf("Alphabetically Ordered String: %s\\n", str);\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'c-pr26', 'title': 'C26: Reverse String In-Place', 'difficulty': 'Foundational', 'category': 'Strings & Pointers', 'question': 'Write a program to reverse a string in-place without using library reverse functions.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="c_rev_str">Copy</button></div>\n<pre><code id="c_rev_str">#include &lt;stdio.h&gt;\n#include &lt;string.h&gt;\n\nvoid reverseString(char *str) {\n    int left = 0;\n    int right = strlen(str) - 1;\n    while (left < right) {\n        char temp = str[left];\n        str[left] = str[right];\n        str[right] = temp;\n        left++;\n        right--;\n    }\n}\n\nint main() {\n    char str[500];\n    printf("Enter string to reverse: ");\n    if (fgets(str, sizeof(str), stdin)) {\n        int len = strlen(str);\n        if (len > 0 && str[len - 1] == \'\\n\') str[len - 1] = \'\\0\';\n        reverseString(str);\n        printf("Reversed: \\"%s\\"\\n", str);\n    }\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds1-q1', 'title': 'DS1-1: Student Ranking System with Tie-Breaking', 'difficulty': 'Intermediate', 'category': 'Classes & Objects', 'question': "Write a C++ program to create class Student with student's rollno, name and marks of three subjects (OOCP, AI and MF) and display the details of student with total marks of all subjects along with the percentage in proper format. Output should be in descending order of percentage. If students have the same percentage, higher marks in MF should be displayed first.", 'solution': '<div class="solution-content">\n<p><strong>Design:</strong> Encapsulates student credentials and utilizes custom comparator sorting with strict secondary tie-breaker on Mathematical Foundations (MF) score.</p>\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_stu1">Copy</button></div>\n<pre><code id="cpp_stu1">#include &lt;iostream&gt;\n#include &lt;string&gt;\n#include &lt;algorithm&gt;\n#include &lt;iomanip&gt;\nusing namespace std;\n\nclass Student {\npublic:\n    int rollNo;\n    string name;\n    float oocp, ai, mf;\n    float total, percentage;\n\n    void input() {\n        cout << "Enter Roll No: ";\n        cin >> rollNo;\n        cin.ignore();\n        cout << "Enter Name: ";\n        getline(cin, name);\n        do {\n            cout << "Enter Marks for OOCP, AI, MF (0-100 each): ";\n            cin >> oocp >> ai >> mf;\n        } while (oocp < 0 || oocp > 100 || ai < 0 || ai > 100 || mf < 0 || mf > 100);\n        calculate();\n    }\n\n    void calculate() {\n        total = oocp + ai + mf;\n        percentage = (total / 300.0f) * 100.0f;\n    }\n\n    void display() const {\n        cout << left << setw(8) << rollNo \n             << setw(20) << name \n             << setw(8) << oocp \n             << setw(8) << ai \n             << setw(8) << mf \n             << setw(10) << total \n             << fixed << setprecision(2) << setw(10) << percentage << "%\\n";\n    }\n};\n\nbool compareStudents(const Student& a, const Student& b) {\n    if (abs(a.percentage - b.percentage) > 0.001f) {\n        return a.percentage > b.percentage; // Descending percentage\n    }\n    return a.mf > b.mf; // Secondary tie-breaker: higher MF marks first\n}\n\nint main() {\n    int n;\n    cout << "Enter number of students: ";\n    cin >> n;\n    Student students[n];\n\n    for (int i = 0; i < n; i++) {\n        cout << "\\n--- Entering Student " << (i + 1) << " ---\\n";\n        students[i].input();\n    }\n\n    sort(students, students + n, compareStudents);\n\n    cout << "\\n========================= MERIT RANK LIST =========================\\n";\n    cout << left << setw(8) << "Roll" << setw(20) << "Name" \n         << setw(8) << "OOCP" << setw(8) << "AI" << setw(8) << "MF" \n         << setw(10) << "Total" << setw(10) << "Percentage" << "\\n";\n    cout << "-------------------------------------------------------------------\\n";\n    for (int i = 0; i < n; i++) {\n        students[i].display();\n    }\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds1-q2', 'title': 'DS1-2: Class Num (Total & Average)', 'difficulty': 'Foundational', 'category': 'Classes & Objects', 'question': 'Write a program to create class Num (int n1, int n2, int n3, int n4). Display total and average of n1, n2, n3 and n4.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_num">Copy</button></div>\n<pre><code id="cpp_num">#include &lt;iostream&gt;\nusing namespace std;\n\nclass Num {\nprivate:\n    int n1, n2, n3, n4;\npublic:\n    Num(int a, int b, int c, int d) : n1(a), n2(b), n3(c), n4(d) {}\n    \n    int getTotal() const { return n1 + n2 + n3 + n4; }\n    double getAverage() const { return getTotal() / 4.0; }\n    \n    void display() const {\n        cout << "Numbers: [" << n1 << ", " << n2 << ", " << n3 << ", " << n4 << "]\\n";\n        cout << "Sum: " << getTotal() << " | Average: " << getAverage() << "\\n";\n    }\n};\n\nint main() {\n    int a, b, c, d;\n    cout << "Enter 4 integers: ";\n    cin >> a >> b >> c >> d;\n    Num obj(a, b, c, d);\n    obj.display();\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds1-q3', 'title': 'DS1-3: Class Time with Minute Addition & 24hr Rollover', 'difficulty': 'Foundational', 'category': 'Classes & Objects', 'question': 'Write a program to create class Time (int h, int m). Read a value as minutes from user to display new time after adding the value to minutes in Time.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_time">Copy</button></div>\n<pre><code id="cpp_time">#include &lt;iostream&gt;\n#include &lt;iomanip&gt;\nusing namespace std;\n\nclass Time {\nprivate:\n    int hours;\n    int minutes;\npublic:\n    Time(int h = 0, int m = 0) {\n        hours = (h + (m / 60)) % 24;\n        minutes = m % 60;\n    }\n\n    void addMinutes(int mins) {\n        int totalMinutes = hours * 60 + minutes + mins;\n        if (totalMinutes < 0) totalMinutes = (totalMinutes % 1440 + 1440) % 1440;\n        hours = (totalMinutes / 60) % 24;\n        minutes = totalMinutes % 60;\n    }\n\n    void display() const {\n        cout << setfill(\'0\') << setw(2) << hours << ":" \n             << setfill(\'0\') << setw(2) << minutes << "\\n";\n    }\n};\n\nint main() {\n    int h, m, add_m;\n    cout << "Enter initial time (hours 0-23 and minutes 0-59): ";\n    cin >> h >> m;\n    Time t(h, m);\n    cout << "Current Time: "; t.display();\n\n    cout << "Enter minutes to add: ";\n    cin >> add_m;\n    t.addMinutes(add_m);\n\n    cout << "Updated Time: "; t.display();\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds1-q4', 'title': 'DS1-4: Class Date with Day Addition & Calendar Leap Handling', 'difficulty': 'Intermediate', 'category': 'Classes & Objects', 'question': 'Write a program to create class Date (int day, int month, int year). Read a value as day from user to display new date after adding the value to day in Date.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_date">Copy</button></div>\n<pre><code id="cpp_date">#include &lt;iostream&gt;\n#include &lt;iomanip&gt;\nusing namespace std;\n\nclass Date {\nprivate:\n    int day, month, year;\n\n    bool isLeapYear(int y) const {\n        return (y % 400 == 0) || (y % 4 == 0 && y % 100 != 0);\n    }\n\n    int daysInMonth(int m, int y) const {\n        int days[] = { 0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31 };\n        if (m == 2 && isLeapYear(y)) return 29;\n        return days[m];\n    }\n\npublic:\n    Date(int d = 1, int m = 1, int y = 2026) : day(d), month(m), year(y) {}\n\n    void addDays(int n) {\n        day += n;\n        while (day > daysInMonth(month, year)) {\n            day -= daysInMonth(month, year);\n            month++;\n            if (month > 12) {\n                month = 1;\n                year++;\n            }\n        }\n    }\n\n    void display() const {\n        cout << setfill(\'0\') << setw(2) << day << "/" \n             << setfill(\'0\') << setw(2) << month << "/" << year << "\\n";\n    }\n};\n\nint main() {\n    int d, m, y, add;\n    cout << "Enter date (day month year): ";\n    cin >> d >> m >> y;\n    Date dt(d, m, y);\n    cout << "Initial Date: "; dt.display();\n\n    cout << "Enter days to add: ";\n    cin >> add;\n    dt.addDays(add);\n    cout << "New Date:     "; dt.display();\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds1-q5', 'title': 'DS1-5: Class Employee with Static Record Tracker & Salary Breakdown', 'difficulty': 'Foundational', 'category': 'Static Members', 'question': "Write a program to create class employee with employee's id, name and basic salary. Calculate gross salary for each employee (HRA 20%, DA 30%, OA 10%). Also count total number of employee records that are entered using static member variables.", 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_emp">Copy</button></div>\n<pre><code id="cpp_emp">#include &lt;iostream&gt;\n#include &lt;string&gt;\n#include &lt;iomanip&gt;\nusing namespace std;\n\nclass Employee {\nprivate:\n    int empId;\n    string name;\n    double basicSalary;\n    double grossSalary;\n    static int recordCount;\n\npublic:\n    Employee() { recordCount++; }\n\n    void input() {\n        cout << "Enter Employee ID: "; cin >> empId;\n        cin.ignore();\n        cout << "Enter Name: "; getline(cin, name);\n        do {\n            cout << "Enter Basic Salary (>= 0): ";\n            cin >> basicSalary;\n        } while (basicSalary < 0);\n        calculateGross();\n    }\n\n    void calculateGross() {\n        double hra = 0.20 * basicSalary;\n        double da  = 0.30 * basicSalary;\n        double oa  = 0.10 * basicSalary;\n        grossSalary = basicSalary + hra + da + oa;\n    }\n\n    void display() const {\n        cout << left << setw(8) << empId << setw(18) << name \n             << fixed << setprecision(2) << setw(12) << basicSalary \n             << setw(12) << grossSalary << "\\n";\n    }\n\n    static int getTotalRecords() { return recordCount; }\n};\n\nint Employee::recordCount = 0;\n\nint main() {\n    int n;\n    cout << "Enter count of employees: ";\n    cin >> n;\n    Employee emp[n];\n\n    for (int i = 0; i < n; i++) {\n        cout << "\\n[Employee " << (i + 1) << "]\\n";\n        emp[i].input();\n    }\n\n    cout << "\\n================== EMPLOYEE PAYROLL ==================\\n";\n    cout << left << setw(8) << "ID" << setw(18) << "Name" \n         << setw(12) << "Basic" << setw(12) << "Gross" << "\\n";\n    cout << "------------------------------------------------------\\n";\n    for (int i = 0; i < n; i++) emp[i].display();\n    cout << "------------------------------------------------------\\n";\n    cout << "Total Employee Records Processed: " << Employee::getTotalRecords() << "\\n";\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds1-q6', 'title': 'DS1-6: Class Book with Price-Ascending Sort (10 Books)', 'difficulty': 'Intermediate', 'category': 'Classes & Objects', 'question': 'Write a program to define a class called book. Write a program to read information about 10 books and display books details in ascending order of price in proper format.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_book">Copy</button></div>\n<pre><code id="cpp_book">#include &lt;iostream&gt;\n#include &lt;string&gt;\n#include &lt;algorithm&gt;\n#include &lt;iomanip&gt;\nusing namespace std;\n\nclass Book {\npublic:\n    int bookId;\n    string title;\n    string author;\n    double price;\n\n    void input() {\n        cout << "Book ID: "; cin >> bookId;\n        cin.ignore();\n        cout << "Title: "; getline(cin, title);\n        cout << "Author: "; getline(cin, author);\n        cout << "Price: "; cin >> price;\n    }\n\n    void display() const {\n        cout << left << setw(8) << bookId << setw(25) << title \n             << setw(20) << author << "$" << fixed << setprecision(2) << price << "\\n";\n    }\n};\n\nbool comparePrice(const Book& a, const Book& b) {\n    return a.price < b.price; // Ascending price\n}\n\nint main() {\n    const int N = 10;\n    Book books[N];\n    cout << "Enter details for " << N << " books:\\n";\n    for (int i = 0; i < N; i++) {\n        cout << "\\n[Book #" << (i + 1) << "]\\n";\n        books[i].input();\n    }\n\n    sort(books, books + N, comparePrice);\n\n    cout << "\\n================== BOOKS (SORTED BY PRICE ASCENDING) ==================\\n";\n    cout << left << setw(8) << "ID" << setw(25) << "Title" \n         << setw(20) << "Author" << "Price" << "\\n";\n    cout << "------------------------------------------------------------------------\\n";\n    for (int i = 0; i < N; i++) books[i].display();\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds1-q7', 'title': 'DS1-7: Class STUDENT with Minimum Passing Marks & Specific Roll Modification', 'difficulty': 'Intermediate', 'category': 'Classes & Objects', 'question': 'Create class STUDENT having rollno, name and age as data members, also take subject with three subjects and initialize their value with minimum passing marks. Using member function, modify marks of student with specific rollno which is given by user.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_stu_mod">Copy</button></div>\n<pre><code id="cpp_stu_mod">#include &lt;iostream&gt;\n#include &lt;string&gt;\nusing namespace std;\n\nclass STUDENT {\nprivate:\n    int rollno;\n    string name;\n    int age;\n    float marks[3]; // 3 subjects initialized to passing 40\n\npublic:\n    STUDENT(int r = 0, string n = "", int a = 18) {\n        rollno = r;\n        name = n;\n        age = a;\n        marks[0] = 40.0f; // Minimum passing mark\n        marks[1] = 40.0f;\n        marks[2] = 40.0f;\n    }\n\n    int getRollNo() const { return rollno; }\n\n    void updateMarks(float m1, float m2, float m3) {\n        marks[0] = m1;\n        marks[1] = m2;\n        marks[2] = m3;\n        cout << "Marks updated successfully for Roll No: " << rollno << "\\n";\n    }\n\n    void display() const {\n        cout << "Roll: " << rollno << " | Name: " << name << " | Age: " << age\n             << " | Marks: [" << marks[0] << ", " << marks[1] << ", " << marks[2] << "]\\n";\n    }\n};\n\nint main() {\n    STUDENT cohort[3] = {\n        STUDENT(101, "Alice", 21),\n        STUDENT(102, "Bob", 22),\n        STUDENT(103, "Charlie", 21)\n    };\n\n    cout << "Default Initialized Cohort (Default min marks = 40):\\n";\n    for (int i = 0; i < 3; i++) cohort[i].display();\n\n    int targetRoll;\n    cout << "\\nEnter Roll Number to modify marks: ";\n    cin >> targetRoll;\n\n    bool found = false;\n    for (int i = 0; i < 3; i++) {\n        if (cohort[i].getRollNo() == targetRoll) {\n            float m1, m2, m3;\n            cout << "Enter new marks for 3 subjects: ";\n            cin >> m1 >> m2 >> m3;\n            cohort[i].updateMarks(m1, m2, m3);\n            cohort[i].display();\n            found = true;\n            break;\n        }\n    }\n    if (!found) cout << "Student with Roll No " << targetRoll << " not found.\\n";\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds1-q8', 'title': 'DS1-8: Bank Account Class Handling 10 Customers', 'difficulty': 'Intermediate', 'category': 'Classes & Objects', 'question': 'Define a class to represent a bank account. Include: Name of depositor, Account Number, Type of Account, Balance amount. Member functions: (1) Assign initial values, (2) Deposit amount, (3) Withdraw amount after checking balance, (4) Display name and balance. Write C++ program to handle 10 customers.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_bank">Copy</button></div>\n<pre><code id="cpp_bank">#include &lt;iostream&gt;\n#include &lt;string&gt;\n#include &lt;iomanip&gt;\nusing namespace std;\n\nclass BankAccount {\nprivate:\n    string depositorName;\n    long long accountNumber;\n    string accountType;\n    double balance;\n\npublic:\n    void init(string name, long long accNo, string type, double initialBal) {\n        depositorName = name;\n        accountNumber = accNo;\n        accountType = type;\n        balance = (initialBal >= 0) ? initialBal : 0.0;\n    }\n\n    void deposit(double amount) {\n        if (amount > 0) {\n            balance += amount;\n            cout << "Deposited $" << amount << ". New Balance: $" << balance << "\\n";\n        } else {\n            cout << "Invalid deposit amount!\\n";\n        }\n    }\n\n    void withdraw(double amount) {\n        if (amount <= 0) {\n            cout << "Invalid withdrawal amount!\\n";\n        } else if (amount > balance) {\n            cout << "Insufficient balance! Current: $" << balance << "\\n";\n        } else {\n            balance -= amount;\n            cout << "Withdrew $" << amount << ". Remaining Balance: $" << balance << "\\n";\n        }\n    }\n\n    void display() const {\n        cout << "Acc: " << accountNumber << " | Holder: " << left << setw(15) \n             << depositorName << " | Type: " << setw(10) << accountType \n             << " | Balance: $" << fixed << setprecision(2) << balance << "\\n";\n    }\n\n    long long getAccNo() const { return accountNumber; }\n};\n\nint main() {\n    const int N = 10;\n    BankAccount accounts[N];\n\n    // Seed 10 sample customers\n    for (int i = 0; i < N; i++) {\n        accounts[i].init("Client_" + to_string(i + 1), 1000100 + i, (i % 2 == 0 ? "Savings" : "Current"), 5000.0 * (i + 1));\n    }\n\n    cout << "=== INITIAL BANK REPOSITORY (10 CUSTOMERS) ===\\n";\n    for (int i = 0; i < N; i++) accounts[i].display();\n\n    // Example transaction\n    cout << "\\nExecuting operations on Account 1000102:\\n";\n    accounts[2].deposit(1250.0);\n    accounts[2].withdraw(3000.0);\n    accounts[2].display();\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds1-q9', 'title': 'DS1-9: Class Search with Static Call Counter', 'difficulty': 'Intermediate', 'category': 'Static Members', 'question': "Write a program to create class 'Search' having data members (int a[], x) and define member functions as void input(), void output(), void search(int position), void add(int value) to display result. Also display how many times search method is called using static count.", 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_search">Copy</button></div>\n<pre><code id="cpp_search">#include &lt;iostream&gt;\nusing namespace std;\n\nclass Search {\nprivate:\n    int a[100];\n    int size;\n    static int searchInvocationCount;\n\npublic:\n    Search() : size(0) {}\n\n    void input() {\n        cout << "Enter number of elements: ";\n        cin >> size;\n        cout << "Enter " << size << " integers: ";\n        for (int i = 0; i < size; i++) cin >> a[i];\n    }\n\n    void output() const {\n        cout << "Array: [";\n        for (int i = 0; i < size; i++) cout << a[i] << (i < size - 1 ? ", " : "");\n        cout << "]\\n";\n    }\n\n    void add(int value) {\n        if (size < 100) {\n            a[size++] = value;\n            cout << "Appended " << value << " at index " << (size - 1) << "\\n";\n        } else {\n            cout << "Array overflow!\\n";\n        }\n    }\n\n    void search(int position) {\n        searchInvocationCount++;\n        if (position >= 0 && position < size) {\n            cout << "Element at index " << position << " is: " << a[position] << "\\n";\n        } else {\n            cout << "Invalid index " << position << "! Bounds are [0.." << size - 1 << "]\\n";\n        }\n    }\n\n    static int getSearchCount() { return searchInvocationCount; }\n};\n\nint Search::searchInvocationCount = 0;\n\nint main() {\n    Search s;\n    s.input();\n    s.output();\n\n    s.search(1);\n    s.search(3);\n    s.add(99);\n    s.search(s.getSearchCount());\n\n    cout << "\\nTotal times search() was invoked: " << Search::getSearchCount() << "\\n";\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds1-q10', 'title': 'DS1-10: Class Wallet with High-Balance & High-Transaction Tracking', 'difficulty': 'Advanced', 'category': 'Classes & Objects', 'question': 'Write a C++ program to create a class Wallet to manage the details and transactions of digital wallets. Data members: Wallet ID, Owner Name, Balance, Transaction Count. Conditions: Initial balance >= Rs 500, Deposit >= Rs 100, Withdrawal allowed only if balance remains >= Rs 500. Display: highest balance wallet, highest transaction wallet, and static total transactions.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_wallet">Copy</button></div>\n<pre><code id="cpp_wallet">#include &lt;iostream&gt;\n#include &lt;string&gt;\n#include &lt;vector&gt;\nusing namespace std;\n\nclass Wallet {\nprivate:\n    int walletId;\n    string ownerName;\n    double balance;\n    int transactionCount;\n    static int totalGlobalTransactions;\n\npublic:\n    Wallet(int id, string name, double initBal) {\n        walletId = id;\n        ownerName = name;\n        balance = (initBal >= 500.0) ? initBal : 500.0;\n        transactionCount = 0;\n    }\n\n    bool deposit(double amount) {\n        if (amount < 100.0) {\n            cout << "Error: Deposit must be at least Rs 100.\\n";\n            return false;\n        }\n        balance += amount;\n        transactionCount++;\n        totalGlobalTransactions++;\n        return true;\n    }\n\n    bool withdraw(double amount) {\n        if (amount <= 0) return false;\n        if (balance - amount < 500.0) {\n            cout << "Error: Withdrawal denied! Balance must remain at least Rs 500.\\n";\n            return false;\n        }\n        balance -= amount;\n        transactionCount++;\n        totalGlobalTransactions++;\n        return true;\n    }\n\n    double getBalance() const { return balance; }\n    int getTxCount() const { return transactionCount; }\n\n    void display() const {\n        cout << "Wallet ID: " << walletId << " | Owner: " << ownerName \n             << " | Balance: Rs " << balance << " | Txns: " << transactionCount << "\\n";\n    }\n\n    static int getGlobalTxCount() { return totalGlobalTransactions; }\n};\n\nint Wallet::totalGlobalTransactions = 0;\n\nint main() {\n    vector&lt;Wallet&gt; wallets = {\n        Wallet(101, "Alice", 1200.0),\n        Wallet(102, "Bob", 600.0),\n        Wallet(103, "Charlie", 2500.0)\n    };\n\n    wallets[0].deposit(500);\n    wallets[0].withdraw(300);\n    wallets[1].deposit(200);\n    wallets[1].withdraw(400); // Should fail minimum balance test\n    wallets[2].deposit(1000);\n    wallets[2].deposit(500);\n\n    cout << "\\n=== ALL WALLETS ===\\n";\n    int highestBalIdx = 0, highestTxIdx = 0;\n    for (size_t i = 0; i < wallets.size(); i++) {\n        wallets[i].display();\n        if (wallets[i].getBalance() > wallets[highestBalIdx].getBalance()) highestBalIdx = i;\n        if (wallets[i].getTxCount() > wallets[highestTxIdx].getTxCount()) highestTxIdx = i;\n    }\n\n    cout << "\\nWallet with Highest Balance:\\n  "; wallets[highestBalIdx].display();\n    cout << "Wallet with Highest Transactions:\\n  "; wallets[highestTxIdx].display();\n    cout << "Global Transactions across all wallets: " << Wallet::getGlobalTxCount() << "\\n";\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds1-q11', 'title': 'DS1-11: Product Inventory Management (10 Products)', 'difficulty': 'Intermediate', 'category': 'Classes & Objects', 'question': 'Write a program to create a class Product having: Product ID, Product Name, Price, Quantity. Create records for 10 products and perform: (1) Display all, (2) Calculate total inventory value, (3) Display highest priced product, (4) Display products whose quantity is less than 10, (5) Search product using Product ID.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_prod">Copy</button></div>\n<pre><code id="cpp_prod">#include &lt;iostream&gt;\n#include &lt;string&gt;\n#include &lt;iomanip&gt;\nusing namespace std;\n\nclass Product {\nprivate:\n    int productId;\n    string productName;\n    double price;\n    int quantity;\n\npublic:\n    void init(int id, string name, double p, int q) {\n        productId = id;\n        productName = name;\n        price = (p > 0) ? p : 1.0;\n        quantity = (q >= 0) ? q : 0;\n    }\n\n    int getId() const { return productId; }\n    double getPrice() const { return price; }\n    int getQty() const { return quantity; }\n    double getValue() const { return price * quantity; }\n\n    void display() const {\n        cout << left << setw(6) << productId << setw(20) << productName \n             << "$" << fixed << setprecision(2) << setw(10) << price \n             << setw(8) << quantity \n             << "$" << setw(12) << getValue() << "\\n";\n    }\n};\n\nint main() {\n    const int N = 10;\n    Product catalog[N];\n\n    // Seed 10 products\n    catalog[0].init(101, "Laptop Core i7", 1100.0, 5);\n    catalog[1].init(102, "Wireless Mouse", 25.0, 50);\n    catalog[2].init(103, "Mechanical Keyboard", 85.0, 8);\n    catalog[3].init(104, "4K IPS Monitor", 450.0, 12);\n    catalog[4].init(105, "USB-C Hub", 35.0, 4);\n    catalog[5].init(106, "Webcam 1080p", 60.0, 15);\n    catalog[6].init(107, "External SSD 1TB", 120.0, 30);\n    catalog[7].init(108, "Noise-Cancel Headset", 199.0, 7);\n    catalog[8].init(109, "Desk Pad XL", 18.0, 40);\n    catalog[9].init(110, "Smart Light Bar", 55.0, 9);\n\n    cout << "=== PRODUCT INVENTORY CATALOG ===\\n";\n    cout << left << setw(6) << "ID" << setw(20) << "Name" << setw(11) << "Price" \n         << setw(8) << "Qty" << "Total Value\\n";\n    cout << "------------------------------------------------------------\\n";\n    double totalInventoryValue = 0.0;\n    int maxPriceIdx = 0;\n\n    for (int i = 0; i < N; i++) {\n        catalog[i].display();\n        totalInventoryValue += catalog[i].getValue();\n        if (catalog[i].getPrice() > catalog[maxPriceIdx].getPrice()) maxPriceIdx = i;\n    }\n    cout << "------------------------------------------------------------\\n";\n    cout << "Total Inventory Worth: $" << totalInventoryValue << "\\n";\n\n    cout << "\\nProduct with Highest Price:\\n  "; catalog[maxPriceIdx].display();\n\n    cout << "\\nLow Stock Products (Quantity < 10):\\n";\n    for (int i = 0; i < N; i++) {\n        if (catalog[i].getQty() < 10) catalog[i].display();\n    }\n\n    // Search by ID\n    int searchId = 105;\n    cout << "\\nSearching for Product ID " << searchId << ":\\n";\n    bool found = false;\n    for (int i = 0; i < N; i++) {\n        if (catalog[i].getId() == searchId) {\n            catalog[i].display();\n            found = true;\n            break;\n        }\n    }\n    if (!found) cout << "Not found.\\n";\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds1-q12', 'title': 'DS1-12: Electricity Bill Calculation (Slab Pricing for 10 Consumers)', 'difficulty': 'Intermediate', 'category': 'Classes & Objects', 'question': 'Create a class Electricity Bill having: Consumer Number, Consumer Name, Previous Meter Reading, Current Meter Reading. Calculate bill according to slabs: First 100 units @ Rs 2/unit, 101-200 @ Rs 3/unit, 201-300 @ Rs 5/unit, Above 300 @ Rs 7/unit. Display consumer details, units, bill amount for 10 consumers, and find consumer with highest bill.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_elec">Copy</button></div>\n<pre><code id="cpp_elec">#include &lt;iostream&gt;\n#include &lt;string&gt;\n#include &lt;iomanip&gt;\nusing namespace std;\n\nclass ElectricityBill {\nprivate:\n    int consumerNo;\n    string consumerName;\n    int prevReading;\n    int currReading;\n    int unitsConsumed;\n    double billAmount;\n\npublic:\n    void init(int no, string name, int prev, int curr) {\n        consumerNo = no;\n        consumerName = name;\n        prevReading = (prev >= 0) ? prev : 0;\n        currReading = (curr >= prevReading) ? curr : prevReading;\n        calculate();\n    }\n\n    void calculate() {\n        unitsConsumed = currReading - prevReading;\n        int u = unitsConsumed;\n        billAmount = 0.0;\n\n        if (u <= 100) {\n            billAmount = u * 2.0;\n        } else if (u <= 200) {\n            billAmount = (100 * 2.0) + (u - 100) * 3.0;\n        } else if (u <= 300) {\n            billAmount = (100 * 2.0) + (100 * 3.0) + (u - 200) * 5.0;\n        } else {\n            billAmount = (100 * 2.0) + (100 * 3.0) + (100 * 5.0) + (u - 300) * 7.0;\n        }\n    }\n\n    double getBill() const { return billAmount; }\n\n    void display() const {\n        cout << left << setw(8) << consumerNo << setw(18) << consumerName \n             << setw(10) << prevReading << setw(10) << currReading \n             << setw(10) << unitsConsumed << "Rs " << fixed << setprecision(2) << billAmount << "\\n";\n    }\n};\n\nint main() {\n    const int N = 10;\n    ElectricityBill bills[N];\n\n    int prevs[] = { 1000, 2400, 1500, 3100, 4000, 1200, 5000, 6200, 1100, 800 };\n    int currs[] = { 1080, 2550, 1750, 3450, 4420, 1230, 5210, 6590, 1310, 990 };\n\n    for (int i = 0; i < N; i++) {\n        bills[i].init(1001 + i, "Consumer_" + to_string(i + 1), prevs[i], currs[i]);\n    }\n\n    cout << "======================== ELECTRICITY BILL STATEMENTS ========================\\n";\n    cout << left << setw(8) << "Cons No" << setw(18) << "Name" \n         << setw(10) << "Prev Rdg" << setw(10) << "Curr Rdg" \n         << setw(10) << "Units" << "Bill Amount\\n";\n    cout << "-----------------------------------------------------------------------------\\n";\n\n    int maxIdx = 0;\n    for (int i = 0; i < N; i++) {\n        bills[i].display();\n        if (bills[i].getBill() > bills[maxIdx].getBill()) maxIdx = i;\n    }\n    cout << "-----------------------------------------------------------------------------\\n";\n    cout << "\\nConsumer with Highest Bill:\\n  "; bills[maxIdx].display();\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds2-q1', 'title': 'DS2-1: Overloading Binary + Operator for Class Numbers', 'difficulty': 'Intermediate', 'category': 'Operator Overloading', 'question': 'WAP to use binary operator + to add two objects of class Numbers having num1 and num2 as its data members and display result.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_oo_add">Copy</button></div>\n<pre><code id="cpp_oo_add">#include &lt;iostream&gt;\nusing namespace std;\n\nclass Numbers {\nprivate:\n    int num1, num2;\npublic:\n    Numbers(int n1 = 0, int n2 = 0) : num1(n1), num2(n2) {}\n\n    // Overloaded binary + operator\n    Numbers operator+(const Numbers& other) const {\n        return Numbers(num1 + other.num1, num2 + other.num2);\n    }\n\n    void display() const {\n        cout << "(num1 = " << num1 << ", num2 = " << num2 << ")\\n";\n    }\n};\n\nint main() {\n    Numbers n1(10, 20);\n    Numbers n2(5, 15);\n    Numbers n3 = n1 + n2;\n\n    cout << "n1: "; n1.display();\n    cout << "n2: "; n2.display();\n    cout << "Result n1 + n2: "; n3.display();\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds2-q2', 'title': 'DS2-2: Overload Operator * to Scale Class arrayContainer', 'difficulty': 'Intermediate', 'category': 'Operator Overloading', 'question': 'WAP to overload operator * which multiplies a scalar number to each element of an array within a class arrayContainer and displays the result.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_arr_scale">Copy</button></div>\n<pre><code id="cpp_arr_scale">#include &lt;iostream&gt;\nusing namespace std;\n\nclass ArrayContainer {\nprivate:\n    int arr[10];\n    int size;\n\npublic:\n    ArrayContainer(int s = 5) : size(s) {\n        for (int i = 0; i < size; i++) arr[i] = (i + 1) * 2;\n    }\n\n    // Overload operator * for scalar multiplication (container * scalar)\n    ArrayContainer operator*(int scalar) const {\n        ArrayContainer result(size);\n        for (int i = 0; i < size; i++) {\n            result.arr[i] = this->arr[i] * scalar;\n        }\n        return result;\n    }\n\n    void display() const {\n        cout << "[ ";\n        for (int i = 0; i < size; i++) cout << arr[i] << " ";\n        cout << "]\\n";\n    }\n};\n\nint main() {\n    ArrayContainer ac(5);\n    cout << "Original Array: "; ac.display();\n\n    ArrayContainer scaled = ac * 3;\n    cout << "Scaled by 3:    "; scaled.display();\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds2-q3', 'title': 'DS2-3: Complex Number Class Overloading (*, +, -, ==, !=, =)', 'difficulty': 'Advanced', 'category': 'Operator Overloading', 'question': 'WAP to overload the *, +, -, ==, != and = operators for the Complex class.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_complex">Copy</button></div>\n<pre><code id="cpp_complex">#include &lt;iostream&gt;\nusing namespace std;\n\nclass Complex {\nprivate:\n    double real, imag;\n\npublic:\n    Complex(double r = 0.0, double i = 0.0) : real(r), imag(i) {}\n\n    // Copy assignment\n    Complex& operator=(const Complex& other) {\n        if (this != &other) {\n            real = other.real;\n            imag = other.imag;\n        }\n        return *this;\n    }\n\n    // Binary +\n    Complex operator+(const Complex& o) const {\n        return Complex(real + o.real, imag + o.imag);\n    }\n\n    // Binary -\n    Complex operator-(const Complex& o) const {\n        return Complex(real - o.real, imag - o.imag);\n    }\n\n    // Binary *\n    Complex operator*(const Complex& o) const {\n        return Complex(real * o.real - imag * o.imag, real * o.imag + imag * o.real);\n    }\n\n    // Equality\n    bool operator==(const Complex& o) const {\n        return (real == o.real && imag == o.imag);\n    }\n\n    // Inequality\n    bool operator!=(const Complex& o) const {\n        return !(*this == o);\n    }\n\n    void display() const {\n        cout << real << (imag >= 0 ? " + " : " - ") << abs(imag) << "i\\n";\n    }\n};\n\nint main() {\n    Complex c1(3, 4), c2(1, -2);\n    cout << "c1 = "; c1.display();\n    cout << "c2 = "; c2.display();\n\n    Complex sum = c1 + c2;\n    Complex diff = c1 - c2;\n    Complex prod = c1 * c2;\n\n    cout << "c1 + c2 = "; sum.display();\n    cout << "c1 - c2 = "; diff.display();\n    cout << "c1 * c2 = "; prod.display();\n    cout << "c1 == c2: " << (c1 == c2 ? "true" : "false") << "\\n";\n    cout << "c1 != c2: " << (c1 != c2 ? "true" : "false") << "\\n";\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds2-q4', 'title': 'DS2-4: Matrix Class with Stream Output Overloading (m1 << cout)', 'difficulty': 'Intermediate', 'category': 'Operator Overloading', 'question': 'WAP to define an object m1 of matrix class, use m1 << cout (and standard stream insertion cout << m1).', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_mat_stream">Copy</button></div>\n<pre><code id="cpp_mat_stream">#include &lt;iostream&gt;\nusing namespace std;\n\nclass Matrix {\nprivate:\n    int mat[2][2];\n\npublic:\n    Matrix() {\n        mat[0][0] = 1; mat[0][1] = 2;\n        mat[1][0] = 3; mat[1][1] = 4;\n    }\n\n    // Member function overloading << for syntax: m1 << cout;\n    void operator<<(ostream& os) const {\n        os << "[" << mat[0][0] << ", " << mat[0][1] << "]\\n"\n           << "[" << mat[1][0] << ", " << mat[1][1] << "]\\n";\n    }\n\n    // Standard friend function for idiomatic: cout << m1;\n    friend ostream& operator<<(ostream& os, const Matrix& m) {\n        m << os;\n        return os;\n    }\n};\n\nint main() {\n    Matrix m1;\n    cout << "Output via m1 << cout syntax:\\n";\n    m1 << cout;\n\n    cout << "\\nOutput via standard cout << m1 syntax:\\n";\n    cout << m1;\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds2-q5', 'title': 'DS2-5: Matrix Scalar Multiplication with Commutative Friend (5 * Matrix)', 'difficulty': 'Intermediate', 'category': 'Operator Overloading', 'question': 'WAP to define a matrix class and overload the * operator to multiply a number with matrix (Example: 5 * Matrix should be possible using friend function).', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_scalar_mat">Copy</button></div>\n<pre><code id="cpp_scalar_mat">#include &lt;iostream&gt;\nusing namespace std;\n\nclass Matrix {\nprivate:\n    int data[2][2];\n\npublic:\n    Matrix(int a=1, int b=2, int c=3, int d=4) {\n        data[0][0]=a; data[0][1]=b;\n        data[1][0]=c; data[1][1]=d;\n    }\n\n    // Member function for: Matrix * scalar\n    Matrix operator*(int scalar) const {\n        return Matrix(data[0][0]*scalar, data[0][1]*scalar,\n                      data[1][0]*scalar, data[1][1]*scalar);\n    }\n\n    // Friend function for: scalar * Matrix (e.g. 5 * m1)\n    friend Matrix operator*(int scalar, const Matrix& m) {\n        return m * scalar;\n    }\n\n    void display() const {\n        cout << "[" << data[0][0] << "  " << data[0][1] << "]\\n"\n             << "[" << data[1][0] << "  " << data[1][1] << "]\\n";\n    }\n};\n\nint main() {\n    Matrix m(2, 3, 4, 5);\n    cout << "Original Matrix:\\n"; m.display();\n\n    Matrix res1 = 5 * m; // 5 * Matrix enabled via friend function\n    cout << "\\nResult of 5 * Matrix:\\n"; res1.display();\n\n    Matrix res2 = m * 2;\n    cout << "\\nResult of Matrix * 2:\\n"; res2.display();\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds2-q6', 'title': 'DS2-6: Class Date Operator Overloading (+, -, =, <, <=, >, >=, ++, --)', 'difficulty': 'Advanced', 'category': 'Operator Overloading', 'question': 'WAP to define a class Date with properties int month, day, year. Overload operators assuming 360-day year and 30-day month: (1) Date + int, (2) Date - int, (3) =, (4) Relational (<, <=, >, >=), (5) Pre/Post ++ and --.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_date_ops">Copy</button></div>\n<pre><code id="cpp_date_ops">#include &lt;iostream&gt;\n#include &lt;iomanip&gt;\nusing namespace std;\n\nclass Date {\nprivate:\n    int day, month, year;\n\n    long toDays() const {\n        return (long)year * 360 + (month - 1) * 30 + day;\n    }\n\n    void fromDays(long totalDays) {\n        year = totalDays / 360;\n        long rem = totalDays % 360;\n        month = (rem / 30) + 1;\n        day = (rem % 30);\n        if (day == 0) { day = 30; month--; }\n    }\n\npublic:\n    Date(int d=1, int m=1, int y=2026) : day(d), month(m), year(y) {}\n\n    // Date + int\n    Date operator+(int days) const {\n        Date temp;\n        temp.fromDays(this->toDays() + days);\n        return temp;\n    }\n\n    // Date - int\n    Date operator-(int days) const {\n        Date temp;\n        temp.fromDays(this->toDays() - days);\n        return temp;\n    }\n\n    // Relational\n    bool operator<(const Date& o) const { return toDays() < o.toDays(); }\n    bool operator<=(const Date& o) const { return toDays() <= o.toDays(); }\n    bool operator>(const Date& o) const { return toDays() > o.toDays(); }\n    bool operator>=(const Date& o) const { return toDays() >= o.toDays(); }\n\n    // Pre-increment\n    Date& operator++() {\n        *this = *this + 1;\n        return *this;\n    }\n\n    // Post-increment\n    Date operator++(int) {\n        Date copy = *this;\n        *this = *this + 1;\n        return copy;\n    }\n\n    // Pre-decrement\n    Date& operator--() {\n        *this = *this - 1;\n        return *this;\n    }\n\n    // Post-decrement\n    Date operator--(int) {\n        Date copy = *this;\n        *this = *this - 1;\n        return copy;\n    }\n\n    void display() const {\n        cout << setfill(\'0\') << setw(2) << day << "/"\n             << setfill(\'0\') << setw(2) << month << "/" << year << "\\n";\n    }\n};\n\nint main() {\n    Date d(28, 5, 2026);\n    cout << "Start: "; d.display();\n    Date d2 = d + 5;\n    cout << "d + 5: "; d2.display();\n    ++d;\n    cout << "++d:   "; d.display();\n    cout << "d < d2: " << (d < d2 ? "true" : "false") << "\\n";\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds2-q7', 'title': 'DS2-7: Class Time Operator Overloading (+, -, =, <, <=, >, >=, ++, --)', 'difficulty': 'Advanced', 'category': 'Operator Overloading', 'question': 'WAP to define a class Time with properties int hour, minute, second. Overload +, -, =, relational, and pre/post ++, -- operators.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_time_ops">Copy</button></div>\n<pre><code id="cpp_time_ops">#include &lt;iostream&gt;\n#include &lt;iomanip&gt;\nusing namespace std;\n\nclass Time {\nprivate:\n    int h, m, s;\n\n    long toSeconds() const { return h * 3600L + m * 60L + s; }\n    void fromSeconds(long sec) {\n        sec = (sec % 86400L + 86400L) % 86400L;\n        h = sec / 3600;\n        sec %= 3600;\n        m = sec / 60;\n        s = sec % 60;\n    }\n\npublic:\n    Time(int hr=0, int min=0, int sec=0) : h(hr), m(min), s(sec) {}\n\n    Time operator+(int sec) const {\n        Time res; res.fromSeconds(this->toSeconds() + sec); return res;\n    }\n    Time operator-(int sec) const {\n        Time res; res.fromSeconds(this->toSeconds() - sec); return res;\n    }\n\n    bool operator<(const Time& o) const { return toSeconds() < o.toSeconds(); }\n    bool operator<=(const Time& o) const { return toSeconds() <= o.toSeconds(); }\n    bool operator>(const Time& o) const { return toSeconds() > o.toSeconds(); }\n    bool operator>=(const Time& o) const { return toSeconds() >= o.toSeconds(); }\n\n    Time& operator++() { *this = *this + 1; return *this; }\n    Time operator++(int) { Time old = *this; *this = *this + 1; return old; }\n    Time& operator--() { *this = *this - 1; return *this; }\n    Time operator--(int) { Time old = *this; *this = *this - 1; return old; }\n\n    void display() const {\n        cout << setfill(\'0\') << setw(2) << h << ":" \n             << setfill(\'0\') << setw(2) << m << ":" \n             << setfill(\'0\') << setw(2) << s << "\\n";\n    }\n};\n\nint main() {\n    Time t1(10, 59, 58);\n    cout << "Initial: "; t1.display();\n    ++t1;\n    cout << "++t1:    "; t1.display();\n    ++t1;\n    cout << "++t1:    "; t1.display();\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds2-q8', 'title': 'DS2-8: Menu-Driven Custom String Class with Overloaded Operators', 'difficulty': 'Advanced', 'category': 'Operator Overloading', 'question': 'Write a menu driven program that can perform the following functions on strings using overloaded operators where possible (without using predefined string library): (1) Equality (==), (2) Comparison (<=), (3) Copy string, (4) Subscript character extraction ([]), (5) Reverse string, (6) Concatenation (+).', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_custom_str">Copy</button></div>\n<pre><code id="cpp_custom_str">#include &lt;iostream&gt;\nusing namespace std;\n\nclass MyString {\nprivate:\n    char* str;\n    int len;\n\n    int computeLength(const char* s) const {\n        int l = 0; while (s && s[l] != \'\\0\') l++; return l;\n    }\n\npublic:\n    MyString(const char* s = "") {\n        len = computeLength(s);\n        str = new char[len + 1];\n        for (int i = 0; i < len; i++) str[i] = s[i];\n        str[len] = \'\\0\';\n    }\n\n    MyString(const MyString& other) {\n        len = other.len;\n        str = new char[len + 1];\n        for (int i = 0; i <= len; i++) str[i] = other.str[i];\n    }\n\n    ~MyString() { delete[] str; }\n\n    // Copy assignment\n    MyString& operator=(const MyString& other) {\n        if (this != &other) {\n            delete[] str;\n            len = other.len;\n            str = new char[len + 1];\n            for (int i = 0; i <= len; i++) str[i] = other.str[i];\n        }\n        return *this;\n    }\n\n    // Equality ==\n    bool operator==(const MyString& other) const {\n        if (len != other.len) return false;\n        for (int i = 0; i < len; i++) {\n            if (str[i] != other.str[i]) return false;\n        }\n        return true;\n    }\n\n    // Lexicographical <=\n    bool operator<=(const MyString& other) const {\n        int minL = (len < other.len) ? len : other.len;\n        for (int i = 0; i < minL; i++) {\n            if (str[i] < other.str[i]) return true;\n            if (str[i] > other.str[i]) return false;\n        }\n        return len <= other.len;\n    }\n\n    // Subscript []\n    char operator[](int idx) const {\n        if (idx >= 0 && idx < len) return str[idx];\n        return \'\\0\';\n    }\n\n    // Concatenate +\n    MyString operator+(const MyString& other) const {\n        char* buf = new char[len + other.len + 1];\n        for (int i = 0; i < len; i++) buf[i] = str[i];\n        for (int j = 0; j < other.len; j++) buf[len + j] = other.str[j];\n        buf[len + other.len] = \'\\0\';\n        MyString res(buf);\n        delete[] buf;\n        return res;\n    }\n\n    void reverse() {\n        int l = 0, r = len - 1;\n        while (l < r) {\n            char t = str[l]; str[l] = str[r]; str[r] = t;\n            l++; r--;\n        }\n    }\n\n    void display() const { cout << str; }\n};\n\nint main() {\n    MyString s1("Data");\n    MyString s2("Structures");\n\n    cout << "s1: "; s1.display(); cout << "\\n";\n    cout << "s2: "; s2.display(); cout << "\\n";\n\n    MyString s3 = s1 + s2;\n    cout << "Concatenation (+): "; s3.display(); cout << "\\n";\n\n    cout << "Char at index 2 of s1: " << s1[2] << "\\n";\n    cout << "s1 == s2: " << (s1 == s2 ? "true" : "false") << "\\n";\n    cout << "s1 <= s2: " << (s1 <= s2 ? "true" : "false") << "\\n";\n\n    s3.reverse();\n    cout << "Reversed concatenation: "; s3.display(); cout << "\\n";\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds2-q9', 'title': 'DS2-9: Generic Number Class Template for Arithmetic (+, -, *, /)', 'difficulty': 'Intermediate', 'category': 'Templates & Generics', 'question': 'Write an object-oriented program to implement a generic Number Class using templates that can accept either int or float data type and perform basic calculation like +, -, / and *.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_gen_num">Copy</button></div>\n<pre><code id="cpp_gen_num">#include &lt;iostream&gt;\nusing namespace std;\n\ntemplate &lt;typename T&gt;\nclass GenericNumber {\nprivate:\n    T val;\n\npublic:\n    GenericNumber(T v = 0) : val(v) {}\n\n    T add(T other) const { return val + other; }\n    T subtract(T other) const { return val - other; }\n    T multiply(T other) const { return val * other; }\n    T divide(T other) const {\n        if (other == 0) {\n            cout << "Division by zero error! ";\n            return 0;\n        }\n        return val / other;\n    }\n\n    void display() const { cout << val; }\n};\n\nint main() {\n    cout << "--- Integer Mode ---\\n";\n    GenericNumber&lt;int&gt; intNum(40);\n    cout << "40 + 12 = " << intNum.add(12) << "\\n";\n    cout << "40 - 15 = " << intNum.subtract(15) << "\\n";\n    cout << "40 * 3  = " << intNum.multiply(3) << "\\n";\n    cout << "40 / 5  = " << intNum.divide(5) << "\\n";\n\n    cout << "\\n--- Float Mode ---\\n";\n    GenericNumber&lt;float&gt; floatNum(17.5f);\n    cout << "17.5 + 2.5 = " << floatNum.add(2.5f) << "\\n";\n    cout << "17.5 / 2.0 = " << floatNum.divide(2.0f) << "\\n";\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds2-q10', 'title': 'DS2-10: Generic Sorting Template Function for Strings, Integers, and Floats', 'difficulty': 'Intermediate', 'category': 'Templates & Generics', 'question': 'Write a generic template function that will sort a character string, integer array, and float array. Create a menu with appropriate options and accept the values from the user.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_gen_sort">Copy</button></div>\n<pre><code id="cpp_gen_sort">#include &lt;iostream&gt;\n#include &lt;string&gt;\nusing namespace std;\n\ntemplate &lt;typename T&gt;\nvoid genericBubbleSort(T arr[], int n) {\n    for (int i = 0; i < n - 1; i++) {\n        for (int j = 0; j < n - i - 1; j++) {\n            if (arr[j] > arr[j + 1]) {\n                T temp = arr[j];\n                arr[j] = arr[j + 1];\n                arr[j + 1] = temp;\n            }\n        }\n    }\n}\n\ntemplate &lt;typename T&gt;\nvoid printArray(T arr[], int n) {\n    for (int i = 0; i < n; i++) cout << arr[i] << " ";\n    cout << "\\n";\n}\n\nint main() {\n    int intArr[] = { 64, 34, 25, 12, 22, 11, 90 };\n    int nInt = sizeof(intArr)/sizeof(intArr[0]);\n    cout << "Original Ints: "; printArray(intArr, nInt);\n    genericBubbleSort(intArr, nInt);\n    cout << "Sorted Ints:   "; printArray(intArr, nInt);\n\n    float floatArr[] = { 3.14f, 1.41f, 2.71f, 0.58f };\n    int nFloat = sizeof(floatArr)/sizeof(floatArr[0]);\n    cout << "\\nOriginal Floats: "; printArray(floatArr, nFloat);\n    genericBubbleSort(floatArr, nFloat);\n    cout << "Sorted Floats:   "; printArray(floatArr, nFloat);\n\n    char charArr[] = { \'z\', \'a\', \'m\', \'c\', \'k\' };\n    int nChar = sizeof(charArr)/sizeof(charArr[0]);\n    cout << "\\nOriginal Chars: "; printArray(charArr, nChar);\n    genericBubbleSort(charArr, nChar);\n    cout << "Sorted Chars:   "; printArray(charArr, nChar);\n    return 0;\n}</code></pre>\n</div>'}, {'id': 'ds2-q11', 'title': 'DS2-11: Template Function find() for Generic Array Lookup', 'difficulty': 'Intermediate', 'category': 'Templates & Generics', 'question': 'Write a template function called find(). This function searches an array for an object. It returns either the index of the matching object (if one is found) or -1 if no match is found.', 'solution': '<div class="solution-content">\n<div class="code-header"><span>C++ Source Code</span><button class="btn btn-sm btn-ghost copy-btn" data-copy="cpp_template_find">Copy</button></div>\n<pre><code id="cpp_template_find">#include &lt;iostream&gt;\n#include &lt;string&gt;\nusing namespace std;\n\ntemplate &lt;typename T&gt;\nint find(const T arr[], int size, const T& target) {\n    for (int i = 0; i < size; i++) {\n        if (arr[i] == target) {\n            return i; // Found at index i\n        }\n    }\n    return -1; // Not found\n}\n\nint main() {\n    int intArr[] = { 10, 20, 30, 40, 50 };\n    int idx1 = find(intArr, 5, 30);\n    cout << "find(intArr, 30): Index " << idx1 << "\\n";\n\n    string strArr[] = { "Alpha", "Beta", "Gamma", "Delta" };\n    int idx2 = find(strArr, 4, string("Gamma"));\n    cout << "find(strArr, \'Gamma\'): Index " << idx2 << "\\n";\n\n    int idx3 = find(strArr, 4, string("Omega"));\n    cout << "find(strArr, \'Omega\'): Index " << idx3 << " (Not found)\\n";\n    return 0;\n}</code></pre>\n</div>'}], 'cheatsheet': [{'title': 'Data Structures Time & Space Complexity Reference', 'content': '\n              <div class="data-table-wrapper">\n                <table class="data-table">\n                  <thead><tr><th>Data Structure</th><th>Access</th><th>Search</th><th>Insertion</th><th>Deletion</th><th>Space</th></tr></thead>\n                  <tbody>\n                    <tr><td>Array</td><td>O(1)</td><td>O(n)</td><td>O(n)</td><td>O(n)</td><td>O(n)</td></tr>\n                    <tr><td>Singly Linked List</td><td>O(n)</td><td>O(n)</td><td>O(1)</td><td>O(1)</td><td>O(n)</td></tr>\n                    <tr><td>Stack</td><td>O(n)</td><td>O(n)</td><td>O(1)</td><td>O(1)</td><td>O(n)</td></tr>\n                    <tr><td>Queue</td><td>O(n)</td><td>O(n)</td><td>O(1)</td><td>O(1)</td><td>O(n)</td></tr>\n                    <tr><td>Binary Search Tree</td><td>O(log n)</td><td>O(log n)</td><td>O(log n)</td><td>O(log n)</td><td>O(n)</td></tr>\n                    <tr><td>Hash Table</td><td>N/A</td><td>O(1)</td><td>O(1)</td><td>O(1)</td><td>O(n)</td></tr>\n                  </tbody>\n                </table>\n              </div>\n            '}]}
